package io.github.miklires.mclans.clan;
import java.util.Locale;import java.util.Set;import java.util.regex.Pattern;
public final class ClanNamingPolicy {private static final Pattern RISKY=Pattern.compile("\\([^)]*[+*][^)]*\\)[+*{]|\\\\[1-9]");private final Pattern name;private final Pattern tag;private final Set<String> reserved;public ClanNamingPolicy(String nameRegex,String tagRegex,Set<String> reserved){name=compile(nameRegex,"[A-Za-z0-9_]{3,16}");tag=compile(tagRegex,"[A-Za-z0-9]{2,5}");this.reserved=reserved.stream().map(String::trim).filter(s->!s.isEmpty()).limit(100).map(s->s.toLowerCase(Locale.ROOT)).collect(java.util.stream.Collectors.toUnmodifiableSet());}public Result validate(String candidate,String candidateTag){if(candidate==null||candidateTag==null||candidate.length()>32||candidateTag.length()>16)return Result.BAD_NAME;if(!name.matcher(candidate).matches())return Result.BAD_NAME;if(!tag.matcher(candidateTag).matches())return Result.BAD_TAG;if(reserved.contains(candidate.toLowerCase(Locale.ROOT))||reserved.contains(candidateTag.toLowerCase(Locale.ROOT)))return Result.RESERVED;return Result.ALLOWED;}private static Pattern compile(String value,String fallback){if(value==null||value.length()>200||RISKY.matcher(value).find()||value.contains("(?<=")||value.contains("(?<!"))return Pattern.compile(fallback);try{return Pattern.compile(value);}catch(java.util.regex.PatternSyntaxException ignored){return Pattern.compile(fallback);}}public enum Result{ALLOWED,BAD_NAME,BAD_TAG,RESERVED}}
